-- Chap Khana brand/menu update v3.0, dated 2026-10.
-- SAFE for existing live databases: never deletes customer orders, and only changes
-- existing menu items if their price is NULL (the original unpriced seed records).
-- The names/prices are transcribed from user-supplied photographs and require
-- OWNER APPROVAL prior to enabling accepting_orders. Different historical
-- photographed menu cards contain contradictory prices. Coffee menu may be
-- offered by a different outlet; verify before launching online checkout.
-- Run AFTER 01_fresh_schema.sql and 03_production_hardening.sql, OR on an
-- existing database that already has public.menu_items and store_settings.

begin;

alter table public.menu_items drop constraint if exists menu_items_category_check;
alter table public.menu_items add constraint menu_items_category_check
  check (category in ('chap','beef','grill','naan','rice','salad','drinks','shakes','coffee','juice','dessert','special','sides'));

on conflict (id) do update set
  category = excluded.category,
  name = excluded.name,
  name_bn = excluded.name_bn,
  description = excluded.description,
  description_bn = excluded.description_bn,
  price = excluded.price,
  image_url = excluded.image_url,
  badge = excluded.badge,
  sort_order = excluded.sort_order
where public.menu_items.price is null;

-- Deactivate the earlier unpriced placeholder; do not remove any paid/owner-edited item.
update public.menu_items set active=false
where id='grilled-chicken' and price is null;

-- DO NOT turn online ordering on automatically. Admin must confirm prices,
-- available items, branch, delivery coverage, and current hours.
commit;
